function event(video,type){return new Promise((resolve,reject)=>{const cleanup=()=>{clearTimeout(timer);video.removeEventListener(type,ok);video.removeEventListener('error',bad)},ok=()=>{cleanup();resolve()},bad=()=>{cleanup();reject(Error('素材无法解码'))};const timer=setTimeout(()=>{cleanup();reject(Error('抽帧超时，请换用 MP4'))},15000);video.addEventListener(type,ok,{once:true});video.addEventListener('error',bad,{once:true})})}
export async function captureEvidence(assets,onProgress=()=>{}){
 if(!assets.length||assets.length>12)throw Error('本地视觉创作每次支持 1–12 份素材，请减少素材数量');
 const count=Math.max(1,Math.min(3,Math.floor(12/assets.length))),frames=[];
 for(let asset=0;asset<assets.length;asset++){const video=document.createElement('video');video.preload='auto';video.muted=true;const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d');try{const ready=event(video,'loadeddata');video.src=assets[asset].url;await ready;const scale=Math.min(320/video.videoWidth,320/video.videoHeight,1);canvas.width=Math.max(1,Math.round(video.videoWidth*scale));canvas.height=Math.max(1,Math.round(video.videoHeight*scale));for(let i=0;i<count;i++){const time=Math.max(0,Math.min(assets[asset].duration-.001,assets[asset].duration*(i+.5)/count));if(Math.abs(video.currentTime-time)>.001){const seek=event(video,'seeked');video.currentTime=time;await seek}ctx.drawImage(video,0,0,canvas.width,canvas.height);frames.push({asset,time,image:canvas.toDataURL('image/jpeg',.65)});onProgress(frames.length,assets.length*count)}}finally{video.pause();video.removeAttribute('src');video.load()}}
 return frames;
}
